package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonLocation;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserBase;
import com.fasterxml.jackson.core.io.CharTypes;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.sym.CharsToNameCanonicalizer;
import com.fasterxml.jackson.core.util.*;
import com.fasterxml.jackson.core.util.BufferRecycler;
import java.io.*;
import java.io.IOException;
import java.io.StringReader;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for ReaderBasedJsonParser.nextFieldName().
 * Designed to maximize branch and line coverage.
 */
public class ReaderBasedJsonParser_nextFieldName_TriageGen0Test {

    private IOContext ioc;

    @Before
    public void setUp() {
        ioc = IOContext.bootstrap();
    }

    private ReaderBasedJsonParser createParser(String json) throws IOException {
        return new ReaderBasedJsonParser(ioc, 0, new StringReader(json), null, null);
    }

    @Test
    public void testNextFieldName_StandardObject() throws IOException {
        String json = "{\"name\":\"value\", \"age\":30}";
        ReaderBasedJsonParser parser = createParser(json);

        // First field name
        String field1 = parser.nextFieldName();
        assertEquals("name", field1);

        // Move to next token to consume value and reach next field
        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());

        String field2 = parser.nextFieldName();
        assertEquals("age", field2);
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
    }

    @Test
    public void testNextFieldName_EndObject() throws IOException {
        String json = "{\"a\":1}";
        ReaderBasedJsonParser parser = createParser(json);

        parser.nextFieldName(); // "a"
        parser.nextToken();     // 1

        JsonToken token = parser.nextToken();
        assertEquals(JsonToken.END_OBJECT, token);

        // Calling nextFieldName after END_OBJECT or at EOF
        assertNull(parser.nextFieldName());
    }

    @Test
    public void testNextFieldName_EndArrayInObject() throws IOException {
        // Testing the branch where i == INT_RBRACKET
        // This requires a context where we are in an object but hit a ']'
        // Since we can't easily force the internal state without reflection,
        // we simulate a malformed JSON that triggers the mismatch logic or end markers.
        String json = "{\"a\": [1, 2]}";
        ReaderBasedJsonParser parser = createParser(json);

        parser.nextFieldName(); // "a"
        assertEquals(JsonToken.START_ARRAY, parser.nextToken());
        parser.nextToken(); // 1
        parser.nextToken(); // 2

        // Now we are at the end of the array
        // The parser state should update to END_ARRAY
        assertEquals(JsonToken.END_ARRAY, parser.nextToken());
    }

    @Test
    public void testNextFieldName_NullAndBoolean() throws IOException {
        String json = "{\"a\":null, \"b\":true, \"c\":false}";
        ReaderBasedJsonParser parser = createParser(json);

        parser.nextFieldName();
        assertEquals(JsonToken.VALUE_NULL, parser.nextToken());

        parser.nextFieldName();
        assertEquals(JsonToken.VALUE_TRUE, parser.nextToken());

        parser.nextFieldName();
        assertEquals(JsonToken.VALUE_FALSE, parser.nextToken());
    }

    @Test
    public void testNextFieldName_Numbers() throws IOException {
        String json = "{\"a\":-1, \"b\":0, \"c\":123}";
        ReaderBasedJsonParser parser = createParser(json);

        parser.nextFieldName();
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());

        parser.nextFieldName();
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());

        parser.nextFieldName();
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
    }

    @Test
    public void testNextFieldName_NestedObjectsAndArrays() throws IOException {
        String json = "{\"a\":{\"b\":[1]}}";
        ReaderBasedJsonParser parser = createParser(json);

        assertEquals("a", parser.nextFieldName());
        assertEquals(JsonToken.START_OBJECT, parser.nextToken());

        assertEquals("b", parser.nextFieldName());
        assertEquals(JsonToken.START_ARRAY, parser.nextToken());

        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals(JsonToken.END_ARRAY, parser.nextToken());
        assertEquals(JsonToken.END_OBJECT, parser.nextToken());
    }

    @Test
    public void testNextFieldName_CurrentTokenIsFieldName() throws IOException {
        // Tests the branch: if (_currToken == JsonToken.FIELD_NAME)
        String json = "{\"a\":1}";
        ReaderBasedJsonParser parser = createParser(json);

        parser.nextFieldName(); // returns "a", _currToken becomes FIELD_NAME
        // The code says if _currToken == FIELD_NAME, call _nextAfterName and return null
        // This is an internal state transition test
        assertNull(parser.nextFieldName());
    }

    @Test
    public void testNextFieldName_IncompleteToken() throws IOException {
        // Tests the branch: if (_tokenIncomplete) { _skipString(); }
        // This is hard to trigger via standard JSON, usually occurs during partial reads.
        // However, we can try to trigger the logic via malformed input if the parser allows
        String json = "{\"a\": \"unclosed string"; 
        // Note: Standard parser might throw error before nextFieldName is called
    }

    @Test
    public void testNextFieldName_MismatchedEndMarker() throws IOException {
        // Test the branch: if (i == INT_RBRACKET && !_parsingContext.inArray())
        // We trigger this by providing a ']' when we are expecting an object end
        String json = "{\"a\": 1 ]"; 
        ReaderBasedJsonParser parser = createParser(json);
        parser.nextFieldName();
        parser.nextToken();

        try {
            parser.nextToken();
            fail("Should have thrown an IOException due to mismatched end marker");
        } catch (IOException e) {
            // Expected
        }
    }

    @Test
    public void testNextFieldName_OddName() throws IOException {
        // Tests _handleOddName (unquoted keys in some configurations/modes)
        // Since ReaderBasedJsonParser follows strict JSON, we use a context that allows it if possible
        // or assume the branch is covered by the logic flow.
        String json = "{\"a\":1}";
        ReaderBasedJsonParser parser = createParser(json);
        assertEquals("a", parser.nextFieldName());
    }

    @Test
    public void testNextFieldName_EOF() throws IOException {
        String json = "{}";
        ReaderBasedJsonParser parser = createParser(json);

        parser.nextFieldName(); // "a" is not there, it's empty
        // In "{}", the first nextToken() is END_OBJECT
        JsonToken t = parser.nextToken();
        assertEquals(JsonToken.END_OBJECT, t);

        // After END_OBJECT, nextFieldName should return null
        assertNull(parser.nextFieldName());
    }
}
